-- Import the coverage / quantity-engine columns from Samak's
-- Plant Specification & Coverage Master workbook onto the existing 348
-- Smart Plant Master rows. Matched by plant_code (the workbook's own
-- "Plant ID" column, e.g. SAMAK-TRE-0001), which is already unique across
-- the catalogue -- confirmed a clean 1:1 match against all 348 rows before
-- writing this migration, so no ambiguity from the duplicate-botanical-name
-- rows kept intentionally elsewhere in the catalogue.
--
-- Pricing columns in the workbook (buy rate, installation rate, plant
-- cost, installation cost, grand total) were empty for every row -- it is
-- a template for per-project pricing, not a pricing source -- so nothing
-- is imported for those; gst_percent/hsn_code/indicative prices are set
-- separately via the app's own "Edit price" dialog.

ALTER TABLE public.plant_species
  ADD COLUMN IF NOT EXISTS planting_method text,
  ADD COLUMN IF NOT EXISTS selected_spacing_m numeric,
  ADD COLUMN IF NOT EXISTS mature_canopy_area_m2 numeric,
  ADD COLUMN IF NOT EXISTS design_coverage_per_plant_m2 numeric,
  ADD COLUMN IF NOT EXISTS plants_per_m2 numeric,
  ADD COLUMN IF NOT EXISTS plants_per_rm numeric,
  ADD COLUMN IF NOT EXISTS default_wastage_percent numeric,
  ADD COLUMN IF NOT EXISTS coverage_notes text,
  ADD COLUMN IF NOT EXISTS install_rate numeric;

UPDATE public.plant_species AS p SET
  planting_method = v.planting_method,
  selected_spacing_m = v.selected_spacing_m,
  mature_canopy_area_m2 = v.mature_canopy_area_m2,
  design_coverage_per_plant_m2 = v.design_coverage_per_plant_m2,
  plants_per_m2 = v.plants_per_m2,
  plants_per_rm = v.plants_per_rm,
  default_wastage_percent = v.default_wastage_percent,
  coverage_notes = v.coverage_notes
FROM (VALUES
